{
  "themes": [
    {
      "cluster": 0,
      "name": "Inconsistent Delivery Status Updates",
      "description": "Customers are frustrated by contradictory tracking information, such as packages marked as failed delivery while simultaneously showing the courier as delayed."
    },
    {
      "cluster": 1,
      "name": "Quiz Winner Selection Transparency",
      "description": "Users are questioning the fairness and transparency of the selection process for app quiz contests, noting that eligible participants often do not win."
    },
    {
      "cluster": 2,
      "name": "Kindle Regional Availability Issues",
      "description": "Customers in specific regions like Portugal are unable to access local Kindle stores or purchase devices due to site redirections and lack of local presence."
    },
    {
      "cluster": 3,
      "name": "Courier Handling and Product Queries",
      "description": "Users are complaining about couriers throwing packages into gardens and asking for specific product details like CD counts in book sets."
    },
    {
      "cluster": 4,
      "name": "Delivery Fee and Rule Clarification",
      "description": "Customers are seeking clarification on whether one-day delivery is paid and inquiring about specific platform rules for promotions or giveaways."
    },
    {
      "cluster": 5,
      "name": "Damaged Package Arrival Conditions",
      "description": "Customers are reporting receiving orders with damaged boxes, missing seals, or no additional packaging, despite fast delivery times."
    },
    {
      "cluster": 6,
      "name": "Prime Delivery Delay Cancellations",
      "description": "Prime members are experiencing significant delays, order cancellations due to driver shortages, and issues with refund processing for undelivered items."
    },
    {
      "cluster": 7,
      "name": "Defective Audio Hardware Arrivals",
      "description": "Customers are receiving headphones and headsets that are damaged, opened, or used despite being ordered as new items."
    },
    {
      "cluster": 8,
      "name": "Prime Video Content and Device Limits",
      "description": "Users are requesting specific movie or TV season additions, asking about app installation capabilities on TV Sticks, and reporting service outages."
    },
    {
      "cluster": 9,
      "name": "Alexa Voice Profile Configuration Errors",
      "description": "Users are unable to train Alexa or create voice profiles due to interface errors, and are requesting features like mid-call number keying."
    },
    {
      "cluster": 10,
      "name": "Pre-Order Game Shipping Failures",
      "description": "Customers are receiving empty cases for pre-ordered games or experiencing significant delays in receiving in-stock titles despite next-day promises."
    },
    {
      "cluster": 11,
      "name": "Kindle Display and Sync Issues",
      "description": "Users are reporting illegible text due to lack of zoom functions, dark screens, and failures with the Send to Kindle feature."
    }
  ]
}
